/* ============ PURE GAME LOGIC ============ */
function mulberry(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const sum4=d=>d[0]+d[1]+d[2]+d[3];
const isMethod=id=>PARTS[id].f==='method';
function stackCost(stack){return stack.reduce((a,id)=>a+PARTS[id].c,0)}
function countLayers(stack){return stack.filter(id=>!isMethod(id)).length}
function countMethods(stack){return stack.filter(isMethod).length}

function evalStack(stack,enemies=[],shield=false){
  const tot=[0,0,0,0], fx=[];
  stack.forEach(id=>PARTS[id].s.forEach((v,i)=>tot[i]+=v));
  const P=stack.map((id,i)=>({id,i})).filter(o=>!isMethod(o.id));
  for(let k=0;k<P.length-1;k++){
    const lo=P[k],hi=P[k+1];
    RULES.forEach(r=>{
      const hit=(r.lo.includes(lo.id)&&r.hi.includes(hi.id))||(r.sym&&r.lo.includes(hi.id)&&r.hi.includes(lo.id));
      if(hit) fx.push({d:r.d,t:r.t,at:hi.i,src:'pair'});
    });
  }
  for(let i=1;i<stack.length;i++) if(isMethod(stack[i]))
    MRULES.forEach(r=>{ if(r.m===stack[i]&&r.below.includes(stack[i-1])) fx.push({d:r.d,t:r.t,at:i,src:'method'}) });
  if(P.length&&P[P.length-1].id==='air') fx.push({d:[0,0,2,0],t:'จบด้วยลมเป่า แห้งไว',at:P[P.length-1].i,src:'top'});
  const has=id=>stack.includes(id), cnt=ids=>stack.filter(id=>ids.includes(id)).length;
  enemies.forEach(e=>{
    if(e==='dust'){
      const dry=cnt(['cloth','broom','air']), wet=cnt(['hot','steam']);
      if(dry) fx.push({d:[dry,0,0,0],t:'Dust แพ้ของแห้ง',at:-1,src:'enemy'});
      if(wet) fx.push({d:[-2*wet,0,0,0],t:'Dust โดนน้ำกลายเป็นโคลน',at:-1,src:'enemy'});
    }
    if(e==='grease'){
      if(has('hot')||has('steam')) fx.push({d:[2,0,0,0],t:'Grease แพ้ความร้อน',at:-1,src:'enemy'});
      else if(stack.length) fx.push({d:[-3,0,0,0],t:'Grease ไม่ออกเพราะไม่มีความร้อน',at:-1,src:'enemy'});
    }
    if(e==='rust'){
      if(has('vinegar')&&(has('scrub')||has('brush'))) fx.push({d:[3,0,0,0],t:'Rust แพ้น้ำส้มสายชูกับแรงขัด',at:-1,src:'enemy'});
      if(has('hot')||has('steam')||has('soak')) fx.push({d:[-2,0,0,0],t:'Rust ลามเพราะโดนน้ำหรือแช่ไว้',at:-1,src:'enemy'});
    }
    if(e==='scale'){
      if(has('vinegar')&&has('soak')) fx.push({d:[3,0,0,0],t:'Scale แพ้น้ำส้มสายชูที่แช่ไว้',at:-1,src:'enemy'});
      if(has('scrub')||has('brush')) fx.push({d:[0,-2,0,0],t:'ขัดแรงบนคราบหินปูน พื้นผิวเป็นรอย',at:-1,src:'enemy'});
    }
  });
  fx.forEach(f=>{f.good=sum4(f.d)>=0;f.off=false});
  if(shield){
    let worst=null;
    fx.forEach(f=>{ if(sum4(f.d)<0&&(!worst||sum4(f.d)<sum4(worst.d))) worst=f });
    if(worst) worst.off=true;
  }
  fx.forEach(f=>{ if(!f.off) f.d.forEach((v,i)=>tot[i]+=v) });
  const stats={}; STATS.forEach((k,i)=>stats[k]=tot[i]);
  return {stats,fx,cost:stackCost(stack),layers:countLayers(stack)};
}
function buildSpec(enemies,round,rng){
  const need={}, notes=[];
  enemies.forEach(e=>Object.entries(ENEMIES[e].need).forEach(([k,v])=>need[k]=Math.max(need[k]||0,v)));
  const pool=EXTRAS.filter(x=>!(need[x.k]>=x.v));
  for(let i=0;i<round-1&&pool.length;i++){
    const x=pool.splice(Math.floor(rng()*pool.length),1)[0];
    need[x.k]=Math.max(need[x.k]||0,x.v); notes.push(x.t);
  }
  return {need,notes};
}
function testScore(stats,spec){
  const ks=Object.keys(spec.need); let acc=0, pass=true;
  ks.forEach(k=>{const r=Math.max(0,Math.min(1,stats[k]/spec.need[k])); acc+=r; if(stats[k]<spec.need[k]) pass=false});
  const base=ks.length?acc/ks.length*100:0;
  return {pass,score:pass?base:base*0.5};
}
function totalScore(stats,spec,budgetLeft,budget,timeFrac){
  const t=testScore(stats,spec);
  const b=Math.max(0,budgetLeft)/budget*100, tm=Math.max(0,Math.min(1,timeFrac))*100;
  return {pass:t.pass,test:t.score,budget:b,time:tm,total:Math.round(0.7*t.score+0.2*b+0.1*tm)};
}
function randomStack(offer,budget,rng){
  const n=2+Math.floor(rng()*4), st=[]; let m=0;
  for(let i=0;i<n;i++){
    const id=offer[Math.floor(rng()*offer.length)];
    if(stackCost(st)+PARTS[id].c>budget) break;
    st.push(id);
    if(m<MAX_METHODS&&rng()<0.3){const mm=METHODS[Math.floor(rng()*3)]; if(stackCost(st)+5<=budget){st.push(mm);m++}}
  }
  return st;
}
function aiBest(offer,spec,enemies,budget,tries,rng,timeFrac){
  let best=null;
  for(let i=0;i<tries;i++){
    const st=randomStack(offer,budget,rng); if(!countLayers(st)) continue;
    const ev=evalStack(st,enemies,false);
    const sc=totalScore(ev.stats,spec,budget-ev.cost,budget,timeFrac);
    if(!best||sc.total>best.sc.total) best={stack:st,ev,sc};
  }
  return best;
}
function makeRound(round,seed){
  const rng=mulberry(seed+round*7919), ids=Object.keys(ENEMIES);
  const pick=()=>ids[Math.floor(rng()*ids.length)];
  for(let attempt=0;attempt<40;attempt++){
    let enemies=[round===1?['stain','dust','grease'][Math.floor(rng()*3)]:pick()];
    if(round===3){let e2=pick(); while(e2===enemies[0]) e2=pick(); enemies.push(e2)}
    const spec=buildSpec(enemies,round,rng);
    const fam=f=>{const a=Object.keys(PARTS).filter(k=>PARTS[k].f===f);for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}; // Fisher-Yates: same result on every JS engine
    const offer=[...fam('tool').slice(0,3),...fam('chem').slice(0,3),...fam('energy').slice(0,2)];
    const chk=aiBest(offer,spec,enemies,ROUND_BUDGET,500,rng,0.3);
    if(chk&&chk.sc.pass) return {round,enemies,spec,offer};
  }
  return {round,enemies:['stain'],spec:{need:{clean:6},notes:[]},offer:['cloth','sponge','brush','soap','vinegar','soda','hot','scrub']};
}

function rpcPing(ctx, logger, nk, payload) {
  return JSON.stringify({ ok: true, game: 'Battle of the Brooms', rules: 'v0.1', parts: Object.keys(PARTS).length });
}
// payload: {"seed":123,"round":1} -> the room both teams receive (same seed = same room)
function rpcMakeRound(ctx, logger, nk, payload) {
  var q = JSON.parse(payload || '{}');
  return JSON.stringify(makeRound(q.round || 1, q.seed || 1));
}
// payload: {"seed":123,"round":1,"stack":["hot","soap"],"budget":100,"timeFrac":0.4,"shield":false,"match":"m123","char":"sweep"}
// match and char are optional; they only label the analytics row this call writes.
function rpcScoreStack(ctx, logger, nk, payload) {
  var q = JSON.parse(payload || '{}');
  var R = makeRound(q.round || 1, q.seed || 1);
  var stack = (q.stack || []).filter(function (id) { return !!PARTS[id]; });
  var allowed = R.offer.concat(METHODS);
  var illegal = stack.filter(function (id) { return allowed.indexOf(id) < 0; });
  var budget = q.budget || ROUND_BUDGET;
  if (illegal.length) throw new Error('parts not offered this round: ' + illegal.join(','));
  if (countLayers(stack) > MAX_LAYERS || countMethods(stack) > MAX_METHODS) throw new Error('stack exceeds limits');
  if (stackCost(stack) > budget) throw new Error('stack exceeds budget');
  var ev = evalStack(stack, R.enemies, !!q.shield);
  var sc = totalScore(ev.stats, R.spec, budget - ev.cost, budget, q.timeFrac || 0);
  logEvent(nk, logger, ctx.userId, cleanMatchId(q.match), 'stack_scored', {
    seed: q.seed || 1, round: q.round || 1, char: CHARS[q.char] ? q.char : null, stack: stack, cost: ev.cost, budget: budget,
    time_frac: q.timeFrac || 0, shield: !!q.shield, stats: ev.stats, score: sc, enemies: R.enemies, need: R.spec.need
  });
  return JSON.stringify({ stats: ev.stats, effects: ev.fx, cost: ev.cost, score: sc, spec: R.spec, enemies: R.enemies });
}
function InitModule(ctx, logger, nk, initializer) {
  initializer.registerRpc('bob_ping', rpcPing);
  initializer.registerRpc('bob_make_round', rpcMakeRound);
  initializer.registerRpc('bob_score_stack', rpcScoreStack);
  // Nakama finds RPCs by reading this function, so every registerRpc must sit here, not in a helper.
  initializer.registerRpc('bob_log_event', rpcLogEvent);
  initializer.registerRpc('bob_analytics', rpcAnalytics);
  createAnalyticsTables(nk);
  logger.info('Battle of the Brooms module loaded');
}

/* ============ ANALYTICS: play events -> Postgres (table bob_events) ============ */
// Every event is one row: who (Nakama user id), which match, what happened, and a JSON payload.
// The server writes `stack_scored` itself whenever it scores a stack, so that number cannot be faked.
// Clients add the rest (match start/end, round results, ability use) through bob_log_event.
var EVENT_SCHEMA = [
  'CREATE TABLE IF NOT EXISTS bob_events (' +
  ' id BIGSERIAL PRIMARY KEY,' +
  ' created_at TIMESTAMPTZ NOT NULL DEFAULT now(),' +
  ' user_id UUID,' +
  ' match_id TEXT,' +
  ' event TEXT NOT NULL,' +
  ' data JSONB NOT NULL DEFAULT \'{}\')',
  'CREATE INDEX IF NOT EXISTS bob_events_event_time ON bob_events (event, created_at)',
  'CREATE INDEX IF NOT EXISTS bob_events_match ON bob_events (match_id)'
];
var CLIENT_EVENTS = { match_start: 1, round_result: 1, ability_used: 1, match_end: 1 };
var MAX_EVENT_BYTES = 4096;

function cleanMatchId(m) {
  if (m == null) return null;
  m = String(m);
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(m)) throw new Error('match id must be 1-64 letters, digits, _ or -');
  return m;
}
function logEvent(nk, logger, userId, matchId, event, data) {
  try {
    nk.sqlExec('INSERT INTO bob_events (user_id, match_id, event, data) VALUES ($1, $2, $3, $4::jsonb)',
      [userId || null, matchId || null, event, JSON.stringify(data || {})]);
  } catch (e) {
    // Analytics must never break gameplay: log and carry on.
    logger.error('bob analytics insert failed: %s', String(e));
  }
}

// payload: {"event":"round_result","match":"m123","data":{...}}
function rpcLogEvent(ctx, logger, nk, payload) {
  if (!ctx.userId) throw new Error('sign in first');
  if ((payload || '').length > MAX_EVENT_BYTES) throw new Error('event too large');
  var q = JSON.parse(payload || '{}');
  if (!CLIENT_EVENTS[q.event]) throw new Error('unknown event: ' + q.event);
  var data = q.data && typeof q.data === 'object' ? q.data : {};
  logEvent(nk, logger, ctx.userId, cleanMatchId(q.match), q.event, data);
  return JSON.stringify({ ok: true });
}

function q1(nk, sql, params) { return nk.sqlQuery(sql, params || []); }
function num(v) { return v == null ? null : Number(v); }

// Server-to-server only (call with ?http_key=...). Players cannot read other players' data.
// payload: {"days":7}
function rpcAnalytics(ctx, logger, nk, payload) {
  if (ctx.userId) throw new Error('analytics is server-to-server only; call with http_key');
  var q = JSON.parse(payload || '{}');
  var days = Math.max(1, Math.min(365, parseInt(q.days, 10) || 7));
  var since = 'now() - ($1 || \' days\')::interval';
  var P = [String(days)];

  var totals = q1(nk,
    'SELECT count(DISTINCT user_id) AS players,' +
    ' count(*) FILTER (WHERE event = \'match_start\') AS matches_started,' +
    ' count(*) FILTER (WHERE event = \'match_end\') AS matches_finished,' +
    ' count(*) FILTER (WHERE event = \'stack_scored\') AS stacks_scored,' +
    ' count(*) FILTER (WHERE event = \'round_result\') AS rounds_played,' +
    ' count(*) AS events' +
    ' FROM bob_events WHERE created_at > ' + since, P)[0];

  var daily = q1(nk,
    'SELECT to_char(date_trunc(\'day\', created_at), \'YYYY-MM-DD\') AS day, event, count(*) AS n' +
    ' FROM bob_events WHERE created_at > ' + since + ' GROUP BY 1, 2 ORDER BY 1, 2', P);

  // Characters: how often picked, how often the match was won, how often the ability got used.
  var chars = q1(nk,
    'WITH m AS (SELECT data->>\'char\' AS char, count(*) AS matches,' +
    '   avg(CASE WHEN (data->>\'wins\')::int > (data->>\'losses\')::int THEN 1.0 ELSE 0.0 END) AS win_rate' +
    '   FROM bob_events WHERE event = \'match_end\' AND created_at > ' + since + ' GROUP BY 1),' +
    ' a AS (SELECT data->>\'char\' AS char, count(*) AS used FROM bob_events' +
    '   WHERE event = \'ability_used\' AND created_at > ' + since + ' GROUP BY 1)' +
    ' SELECT m.char, m.matches, m.win_rate, coalesce(a.used, 0) AS abilities_used' +
    ' FROM m LEFT JOIN a ON a.char = m.char ORDER BY m.matches DESC', P);

  // Parts: from the server's own scoring, how often each part is used and what it scores.
  var parts = q1(nk,
    'SELECT p.part, count(*) AS uses, count(DISTINCT e.id) AS stacks,' +
    ' avg((e.data->\'score\'->>\'total\')::numeric) AS avg_total,' +
    ' avg(CASE WHEN (e.data->\'score\'->>\'pass\')::boolean THEN 1.0 ELSE 0.0 END) AS pass_rate' +
    ' FROM bob_events e, jsonb_array_elements_text(e.data->\'stack\') AS p(part)' +
    ' WHERE e.event = \'stack_scored\' AND e.created_at > ' + since +
    ' GROUP BY 1 ORDER BY 2 DESC', P);

  // Part win rate: rounds won against the rival when this part was in the stack.
  var partWins = q1(nk,
    'SELECT p.part, count(DISTINCT e.id) AS rounds,' +
    ' avg(CASE WHEN e.data->>\'result\' = \'win\' THEN 1.0 ELSE 0.0 END) AS win_rate' +
    ' FROM bob_events e, LATERAL (SELECT DISTINCT x FROM jsonb_array_elements_text(e.data->\'stack\') AS t(x)) AS p(part)' +
    ' WHERE e.event = \'round_result\' AND e.created_at > ' + since +
    ' GROUP BY 1', P);

  var rounds = q1(nk,
    'SELECT (data->>\'round\')::int AS round, count(*) AS n,' +
    ' avg((data->>\'my_total\')::numeric) AS avg_total,' +
    ' avg((data->>\'rival_total\')::numeric) AS avg_rival,' +
    ' avg(CASE WHEN data->>\'result\' = \'win\' THEN 1.0 ELSE 0.0 END) AS win_rate,' +
    ' avg(CASE WHEN (data->>\'pass\')::boolean THEN 1.0 ELSE 0.0 END) AS pass_rate,' +
    ' avg((data->>\'time_left\')::numeric) AS avg_time_left' +
    ' FROM bob_events WHERE event = \'round_result\' AND created_at > ' + since +
    ' GROUP BY 1 ORDER BY 1', P);

  // Enemy line-ups: which rooms are too hard (low spec pass rate).
  var enemies = q1(nk,
    'SELECT (SELECT string_agg(x, \' + \' ORDER BY x) FROM jsonb_array_elements_text(data->\'enemies\') AS t(x)) AS enemies,' +
    ' count(*) AS stacks,' +
    ' avg(CASE WHEN (data->\'score\'->>\'pass\')::boolean THEN 1.0 ELSE 0.0 END) AS pass_rate,' +
    ' avg((data->\'score\'->>\'total\')::numeric) AS avg_total' +
    ' FROM bob_events WHERE event = \'stack_scored\' AND created_at > ' + since +
    ' GROUP BY 1 ORDER BY 3', P);

  var layers = q1(nk,
    'SELECT jsonb_array_length(data->\'stack\') AS size, count(*) AS n,' +
    ' avg((data->\'score\'->>\'total\')::numeric) AS avg_total' +
    ' FROM bob_events WHERE event = \'stack_scored\' AND created_at > ' + since +
    ' GROUP BY 1 ORDER BY 1', P);

  var recent = q1(nk,
    'SELECT id, to_char(created_at, \'YYYY-MM-DD HH24:MI:SS\') AS at, user_id::text AS user_id, match_id, event, data::text AS data' +
    ' FROM bob_events ORDER BY id DESC LIMIT 40', []);

  var pw = {};
  partWins.forEach(function (r) { pw[r.part] = r; });
  return JSON.stringify({
    days: days,
    generated_at: new Date().toISOString(),
    totals: {
      players: num(totals.players), matches_started: num(totals.matches_started), matches_finished: num(totals.matches_finished),
      stacks_scored: num(totals.stacks_scored), rounds_played: num(totals.rounds_played), events: num(totals.events)
    },
    daily: daily.map(function (r) { return { day: r.day, event: r.event, n: num(r.n) }; }),
    characters: chars.map(function (r) {
      return { char: r.char, name: CHARS[r.char] ? CHARS[r.char].n : r.char, matches: num(r.matches), win_rate: num(r.win_rate), abilities_used: num(r.abilities_used) };
    }),
    parts: parts.map(function (r) {
      var w = pw[r.part] || {};
      return { part: r.part, name: PARTS[r.part] ? PARTS[r.part].n : r.part, family: PARTS[r.part] ? PARTS[r.part].f : null,
        cost: PARTS[r.part] ? PARTS[r.part].c : null, uses: num(r.uses), stacks: num(r.stacks), avg_total: num(r.avg_total),
        pass_rate: num(r.pass_rate), win_rate: num(w.win_rate), win_rounds: num(w.rounds) };
    }),
    rounds: rounds.map(function (r) {
      return { round: num(r.round), n: num(r.n), avg_total: num(r.avg_total), avg_rival: num(r.avg_rival), win_rate: num(r.win_rate),
        pass_rate: num(r.pass_rate), avg_time_left: num(r.avg_time_left) };
    }),
    enemies: enemies.map(function (r) {
      var names = (r.enemies || '').split(' + ').map(function (k) { return ENEMIES[k] ? ENEMIES[k].n : k; }).join(' + ');
      return { enemies: r.enemies, name: names, stacks: num(r.stacks), pass_rate: num(r.pass_rate), avg_total: num(r.avg_total) };
    }),
    stack_sizes: layers.map(function (r) { return { size: num(r.size), n: num(r.n), avg_total: num(r.avg_total) }; }),
    recent: recent.map(function (r) {
      return { id: num(r.id), at: r.at, user_id: r.user_id, match_id: r.match_id, event: r.event, data: JSON.parse(r.data) };
    })
  });
}

function createAnalyticsTables(nk) {
  EVENT_SCHEMA.forEach(function (sql) { nk.sqlExec(sql, []); });
}
